<script setup lang="ts">
import {ref} from 'vue'
import OperationForm from './OperationForm.vue'
import {api,upload,download,errorText} from '../api/client'
const props=defineProps<{user:any}>();const emit=defineEmits(['passwordChanged'])
const passwordOpen=ref(!!props.user?.mustChangePassword),files=ref<any[]>([]),objectKey=ref(''),busy=ref(false),error=ref(''),transcript=ref('')
async function sendFile(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;busy.value=true;error.value='';try{const r=await upload(file);files.value.unshift({...r,name:file.name});objectKey.value=r.objectKey}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function transcribe(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;busy.value=true;error.value='';try{const form=new FormData();form.append('file',f);const data=await api.post('/transcriptions',form);transcript.value=data.text||''}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">ACCOUNT & SERVICES</span><h1>账号与附件</h1><p>{{user.mustChangePassword?'请先修改初始密码，之后重新登录进入服务。':'维护账号安全，管理本次上传的附件和语音转写草稿。'}}</p></div></div><section class="paper"><h3>登录账号</h3><p>{{user.username}} · {{user.realName}}</p><button class="btn primary" @click="passwordOpen=true">{{user.mustChangePassword?'修改初始密码':'修改密码'}}</button></section><template v-if="!user.mustChangePassword"><section class="paper file-service"><h3>私有附件</h3><p>附件随当前账号授权读取，不通过公开静态地址展示。</p><input type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.txt,.png,.jpg,.jpeg" :disabled="busy" @change="sendFile"><ul><li v-for="f in files" :key="f.objectKey"><span>{{f.name}}</span><button class="text-link" @click="download('/files/'+encodeURIComponent(f.objectKey),f.name)">下载</button></li></ul><label>已有附件编号<input v-model="objectKey" placeholder="粘贴业务记录中的附件编号"></label><button class="btn outline" :disabled="!objectKey" @click="download('/files/'+encodeURIComponent(objectKey),'附件').catch(e=>error=errorText(e))">下载附件</button></section><section class="paper file-service"><h3>语音转写草稿</h3><p>上传工作录音后，先核对转写内容，再用于业务表单。未配置语音供应商时会明确提示暂不可用。</p><input type="file" accept="audio/*" :disabled="busy" @change="transcribe"><label v-if="transcript">核对转写内容<textarea v-model="transcript" rows="6"></textarea></label><p v-if="transcript" class="info-box">转写尚未提交任何业务。请核对后复制到对应表单。</p></section></template><p v-if="error" class="error-callout" role="alert">{{error}}</p><OperationForm v-if="passwordOpen" path="/api/v1/auth/password-change" method="POST" title="修改密码" @close="passwordOpen=false" @saved="emit('passwordChanged')"/></section></template>
